'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TITLES={p1:['工作台','总览 / 今日待办'],p2:['AI 安全助手','小安 · 规范检索与文书生成'],p6:['隐患办理','双 Agent 协作 · 人工签发'],p3:['隐患台账','双轨闭环管理'],p4:['AI 监控','领导驾驶舱 · 态势统计'],p5:['知识库','查依据 · 管资料']};
let CUR_USER=null,token=localStorage.getItem('safety_token')||'',toastTimer,authGeneration=0,chatAbort=null;
async function api(path,method='GET',body){
  const headers={Authorization:'Bearer '+token};if(body && !(body instanceof FormData))headers['Content-Type']='application/json';
  const origin=/^\/api\/(monitor\/|dashboard\/summary)/.test(path)?await monitorOrigin():'';
  let r,monitorUnavailable=false;const options={method,headers,body:body?(body instanceof FormData?body:JSON.stringify(body)):undefined};
  try{r=await fetch(origin+path,options);if(origin&&path==='/api/dashboard/summary'&&r.status>=500){r=await fetch(path,options);monitorUnavailable=true;}}
  catch(e){if(origin&&path==='/api/dashboard/summary'){r=await fetch(path,options);monitorUnavailable=true;}else throw Error(origin?'监控服务连接失败，请检查独立监控服务':'网络连接失败，请重试');}
  const data=await r.json();if(headers.Authorization!=='Bearer '+token)throw Error('身份已切换，旧请求已忽略');if(!r.ok){if(r.status===401)toLogin();throw Error(data.message||'请求失败');}if(monitorUnavailable)data.data.monitor_today=null;return data.data;
}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function openModal(t,b,f=''){clearHazardPreviews();$('mTitle').textContent=t;$('mBody').innerHTML=b;$('mFoot').innerHTML=f;$('mask').classList.add('on');}
function closeModal(){clearHazardPreviews();$('mask').classList.remove('on');}
function go(id,el){if(!CUR_USER)return toLogin();document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===id));$('tb-title').textContent=TITLES[id][0];$('tb-crumb').textContent=TITLES[id][1];if(window['load_'+id])window['load_'+id]().catch(toast);}
function applyUser(){for(const prefix of ['sb','tb']){$(prefix+'Avatar').textContent=CUR_USER.display_name[0];$(prefix+'Name').textContent=CUR_USER.display_name;$(prefix+'Role').textContent=CUR_USER.role;}$('sbId').textContent='工号 '+CUR_USER.employee_no;$('p1Name').textContent=CUR_USER.display_name;refreshKbCount().catch(e=>toast(e.message));}
async function doLogin(){try{const d=await api('/api/auth/login','POST',{username:$('lgUser').value,password:document.querySelector('#loginGate input[type=password]').value});token=d.token;localStorage.setItem('safety_token',token);CUR_USER=d.user;applyUser();$('loginGate').classList.remove('on');go('p1');toast('欢迎回来，'+CUR_USER.display_name);}catch(e){toast(e.message);}}
async function toLogin(msg){const old=token;authGeneration++;chatAbort?.abort();chatAbort=null;chatBusy=false;curSessId=null;chatSource=null;SESS=[];selectedHazard=null;p6Task=null;p6Hazard=null;clearTimeout(p6Timer);clearTimeout(monitorTimer);monitorRun=null;monitorLatest=[];monitorFrames={};monitorImageSeq++;monitorFrameId=null;if(monitorFrameUrl){URL.revokeObjectURL(monitorFrameUrl);monitorFrameUrl=null;}$('vwResult').hidden=true;if(patrolT){clearInterval(patrolT);patrolT=null;}token='';CUR_USER=null;localStorage.removeItem('safety_token');$('umenu').classList.remove('on');$('ntfPanel').classList.remove('on');closeModal();$('chat').innerHTML=greetHtml();$('loginGate').classList.add('on');if(old)fetch('/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+old}}).catch(()=>{});if(msg)toast(msg);}
function toggleUmenu(e){e.stopPropagation();$('umenu').classList.toggle('on');}
function toggleNtf(e){e.stopPropagation();$('ntfPanel').classList.toggle('on');}
function ntfGo(e,pg){e.stopPropagation();$('ntfPanel').classList.remove('on');go(pg);}
function showProfile(){openModal('个人信息设置',`<div class="frm"><p>姓名：${esc(CUR_USER.display_name)}</p><p>岗位：${esc(CUR_USER.role)}</p><p>工号：${esc(CUR_USER.employee_no)}</p><p>项目：${esc(CUR_USER.project)}</p><p class="frm-tip">演示账号由本地管理员维护，用于操作留痕和会话归属。</p></div>`,'<button class="btn" onclick="closeModal()">关闭</button>');}
let selectedHazard=null,selectedSnapshot=null,curF='all';
async function load_p1(){const s=await api('/api/dashboard/summary');const p=$('p1');p.querySelector('.page-head .d').textContent=`今天是 ${s.today} ${s.weekday} · 本周已闭环 ${s.week_closed} 条隐患 · 系统运行正常`;
  const hour=Number(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'numeric',hourCycle:'h23'}).format(new Date()));p.querySelector('.page-head .t').innerHTML=`${hour<6?'夜深了':hour<12?'上午好':hour<18?'下午好':'晚上好'}，<span id="p1Name">${esc(CUR_USER.display_name)}</span> 👋`;
  const nums=p.querySelectorAll('.stat-grid .stat-num');[s.pending_review,s.overdue,s.today_new,s.month_rate+'%'].forEach((n,i)=>nums[i].textContent=n);const subs=p.querySelectorAll('.stat-grid .stat-sub');subs[2].textContent=`含已确认 AI 来源 ${s.today_new_ai} 条`;subs[3].textContent=`较上月 ${s.month_rate_delta>=0?'+':''}${s.month_rate_delta} 个百分点`;
  p.querySelector('.wl').innerHTML=s.todos.map(t=>`<div class="wi"><div class="ic">${t.priority===0?'🔴':t.priority===1?'🟠':'🔵'}</div><div class="bd"><div class="tt">${esc(t.title)}${t.overdue_days?' · 已逾期 '+t.overdue_days+' 天':''}</div><div class="ss">${esc(t.team||'AI 抓拍线索')} · ${esc(t.status)}${t.deadline?' · 期限 '+esc(t.deadline):''}</div></div><button class="btn sm ${t.priority===0?'primary':''}" onclick="${t.type==='snapshot'?'focusSnapshot('+t.snapshot_id+')':t.type==='review'?'openReview('+t.hazard_id+')':'focusHazard('+t.hazard_id+')'}">${t.type==='snapshot'?'查看监控':t.type==='review'?'复查':'去处理'}</button></div>`).join('')||'<div class="empty">暂无待办事项</div>';
  const chips=p.querySelector('.card-h');chips.querySelector('.chip.red').textContent=s.overdue+' 逾期';chips.querySelector('.chip.amber').textContent=s.pending_review+' 待复查';
  renderHomeMonitor(s.monitor_today);
  p.querySelectorAll('.quick')[1].setAttribute('onclick','goP6()');
  $('ntfPanel').innerHTML='<div class="nh">通知提醒 · '+s.todos.length+' 项待办</div>'+s.todos.slice(0,3).map(t=>`<div class="ni" onclick="${t.type==='snapshot'?'focusSnapshot('+t.snapshot_id+')':'focusHazard('+t.hazard_id+')'}"><span class="dot"></span><div><div class="nt">${esc(t.title)}</div><div class="ns">${esc(t.status)}</div></div></div>`).join('');
  if(!canOperate()){p.querySelector('.page-head .d').textContent+=' · 项目总监督办视角';p.querySelectorAll('.wi button').forEach((b,i)=>{b.textContent='督办';b.setAttribute('onclick','urgeModal('+s.todos[i].hazard_id+')');});}
  const registration=p.querySelectorAll('.quick')[2];registration.setAttribute('onclick',canOperate()?'openHzModal()':"go('p3')");registration.querySelector('.qt')?.replaceChildren(document.createTextNode(canOperate()?'登记隐患':'查看隐患台账'));
}
function urgeModal(id){openModal('项目总监督办','<div class="frm"><label>督办意见 *</label><textarea id="urgeNote" placeholder="记录实际督办意见"></textarea></div>',`<button class="btn primary" onclick="hazardAction(${id},'urge',$('urgeNote').value)">保存督办记录</button><button class="btn" onclick="focusHazard(${id})">查看事项</button>`);}
function goP6(id){selectedHazard=id||null;go('p6');}
function focusSnapshot(id){selectedSnapshot=id;go('p4');setMode('normal');}
async function focusHazard(id){selectedHazard=id;go('p3');if(window.viewHazard)return viewHazard(id);const h=await api('/api/hazards/'+id);openModal('隐患详情',`<p>${esc(h.title)}</p><p>${esc(h.status)} · ${esc(h.responsible_team)}</p>`,'<button class="btn" onclick="closeModal()">关闭</button>');}
function setMode(mode){$('m-normal').classList.toggle('on',mode==='normal');$('m-board').classList.toggle('on',mode==='board');$('board').classList.toggle('on',mode==='board');$('normal').style.display=mode==='board'?'none':'block';}
async function openReview(id){selectedHazard=id;go('p3');const h=await api('/api/hazards/'+id);if(h.status!=='待复查')return toast('当前状态不是待复查，请刷新台账');openModal('复查销项',`<div class="frm"><h3>${esc(h.title)}</h3><p>${h.is_demo?'<b class="chip amber">演示模拟案例</b> ':''}${esc(h.code)} · ${esc(h.status)}<br>责任班组：${esc(h.responsible_team||'未记录')} · 责任人：${esc(h.responsible_person||'未记录')}</p><h4>班组整改反馈</h4>${hazardFeedbackHtml(h)}<h4>整改证据附件</h4>${rectifyEvidenceHtml(h)}<label>安全员复查意见 *</label><textarea id="reviewNote" placeholder="现场复查后填写，例如：整改合格"></textarea><p class="frm-tip">班组反馈不代表已完成现场复查；请现场核实后填写本次结论。</p></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn" onclick="hazardAction(${id},'review_return',$('reviewNote').value,${h.version})">不合格 · 退回整改</button><button class="btn primary" onclick="hazardAction(${id},'review_close',$('reviewNote').value,${h.version})">复查合格并销项</button>`);hydrateRectifyEvidence(h);}
async function hazardAction(id,action,note='',version=null){const body={action,note};if(version!==null)body.version=version;await api('/api/hazards/'+id+'/actions','POST',body);closeModal();if(window.load_p3)await load_p3();if(window.load_p6&&$('p6').classList.contains('active'))await load_p6();await load_p1();if(action==='review_close'){toast('现场复查结论已记录，隐患已销项归档');return viewHazard(id);}toast(action==='urge'?'已记录催办，未对接外部通知':'操作已保存并留痕');}
function openHzModal(){openModal('＋ 登记新隐患',`<div class="frm"><label>隐患描述 *</label><textarea id="hzD" placeholder="例：5#楼二层楼梯口防护栏杆缺失"></textarea><div class="row2"><div><label>处理轨道</label><select id="hzT"><option value="heavy">限期整改 · 重轨</option><option value="light">即查即改 · 轻轨</option></select></div><div><label>责任班组</label><input id="hzW" placeholder="填写责任班组"></div></div><div class="row2"><div><label>责任人</label><input id="hzPerson" placeholder="未确定可留空，签发前必填"></div><div><label>整改期限</label><input id="hzDl" type="date"></div></div><label>现场位置</label><input id="hzLoc"><div class="frm-tip">人工巡查登记。AI 监控线索请在监控页现场确认后入账。</div></div>`,'<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="submitHz()">登记并进入闭环</button>');}
async function submitHz(){const h=await api('/api/hazards','POST',{title:$('hzD').value.trim(),description:$('hzD').value.trim(),track:$('hzT').value,responsible_team:$('hzW').value.trim(),responsible_person:$('hzPerson').value.trim(),deadline:$('hzDl').value||null,location:$('hzLoc').value});closeModal();selectedHazard=h.id;if(window.load_p3&&$('p3').classList.contains('active'))await load_p3();if($('p1').classList.contains('active'))await load_p1();toast('已登记 '+h.code+' · 待人工办理');}
function presetAsk(kind){if(kind==='文书')return goP6();go('p2');if(window.ask)ask('基坑临边防护有什么要求？');}
let SESS=[],curSessId=null,chatBusy=false,chatSource=null;
const greetHtml=()=>'<div class="msg ai"><div class="av">安</div><div class="bub">你好，我是<b>小安</b>，项目部的数字化安全员。你可以问我规范条款、让我生成整改文书，我都会基于知识库的法规原文回答，并附上出处。试试左侧的快捷提问 👈</div></div>';
function sessionKey(){return 'safety_session_'+CUR_USER.id;}
function renderSessList(){$('sessCnt').textContent=SESS.length+' 条';$('chatList').innerHTML=SESS.map(s=>`<div class="sess ${s.id===curSessId?'on':''}" onclick="loadChat('${s.id}')"><div class="st">${esc(s.title)}</div><div class="sm2"><span>${esc(s.updated_at.slice(5,16))}</span><span class="del" onclick="delSess(event,'${s.id}')">✕</span></div></div>`).join('')||'<div class="empty">暂无历史对话</div>';}
async function refreshSessions(){SESS=await api('/api/sessions');renderSessList();}
async function load_p2(){await refreshSessions();if(chatBusy)return;if(!curSessId)curSessId=localStorage.getItem(sessionKey());if(curSessId&&SESS.some(s=>s.id===curSessId))await loadChat(curSessId);else{$('chat').innerHTML=greetHtml();curSessId=null;}renderSessList();const rid=localStorage.getItem('safety_run_'+CUR_USER.id);if(rid)recoverRun(rid);}
async function newChat(){curSessId=null;chatSource=null;localStorage.removeItem(sessionKey());$('chat').innerHTML=greetHtml();await refreshSessions();toast('已开始新对话');}
function citationHtml(refs){return refs.map(r=>`<button class="btn sm" style="white-space:normal;text-align:left" onclick="kbLocate(${r.source_id},'${esc(r.chunk_id)}')">📚 ${esc(r.doc_no)} · ${esc(r.section)} · ${esc(r.chunk_id)}</button>`).join('');}
function appendMessage(role,text,refs=[]){const el=document.createElement('div');el.className='msg '+(role==='user'?'user':'ai');el.innerHTML=`<div class="av">${role==='user'?esc(CUR_USER.display_name[0]):'安'}</div><div class="bub"><div class="message-text" style="white-space:pre-wrap;overflow-wrap:anywhere"></div><div class="message-refs" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:12px"></div></div>`;el.querySelector('.message-text').textContent=text;el.querySelector('.message-refs').innerHTML=citationHtml(refs);$('chat').appendChild(el);$('chat').scrollTop=$('chat').scrollHeight;return el;}
async function loadChat(id){const messages=await api('/api/sessions/'+id+'/messages');curSessId=id;localStorage.setItem(sessionKey(),id);$('chat').innerHTML=greetHtml();for(const m of messages)appendMessage(m.role,m.content,JSON.parse(m.sources||'[]'));renderSessList();}
async function delSess(e,id){e.stopPropagation();await api('/api/sessions/'+id,'DELETE');if(curSessId===id){curSessId=null;localStorage.removeItem(sessionKey());$('chat').innerHTML=greetHtml();}await refreshSessions();}
async function ask(q){q=(q||'').trim();if(!q)return;if(chatBusy)return toast('当前回答正在生成，请稍候');if(/通知单|整改文书|办理文书/.test(q)){appendMessage('user',q);const el=appendMessage('assistant','正式隐患文书请在隐患办理工作台进行双 Agent 复核和人工签发。');el.querySelector('.message-refs').innerHTML='<button class="btn primary" onclick="goP6()">前往隐患办理工作台 →</button>';return;}
  const generation=authGeneration;chatAbort=new AbortController();chatBusy=true;$('q').value='';appendMessage('user',q);const el=appendMessage('assistant','正在检索知识库原文…');const out=el.querySelector('.message-text');
  try{if(/JSA|班前安全分析|技术交底|安全日志/.test(q)){const kind=/JSA|班前/.test(q)?'jsa':/交底/.test(q)?'jiaodi':'log';const d=await api('/api/draft','POST',{kind,context:q,session_id:curSessId});curSessId=d.session_id;localStorage.setItem(sessionKey(),curSessId);out.textContent=(d.mode==='offline'?'当前为离线兜底结果\n':'')+'草稿待审核 · '+d.title+'\n\n'+d.content.body;el.querySelector('.message-refs').innerHTML=citationHtml(d.content.evidence)+`<button class="btn sm primary" onclick="saveDraft(${d.id})">保存为草稿</button><button class="btn sm" onclick="downloadFile('/api/documents/${d.id}/export','草稿-${d.id}.docx')">导出 Word 草稿</button>`;}
  else if(/监控线索|巡查建议/.test(q)){const s=await api('/api/dashboard/summary'),m=s.monitor_today;if(!m)out.textContent='监控统计暂不可用，请检查独立监控服务。';else{const {real:r,demo:d}=monitorGroups(m);out.textContent=`今日真实 YOLO 安全帽线索 ${r.no_helmet} 条：待确认 ${r.pending_today}、已确认 ${r.confirmed_today}、已驳回 ${r.dismissed_today}。真实待确认含历史积压 ${r.pending} 条。\n演示数据单列：今日未驳回 ${d.violations} 条，安全帽 ${d.no_helmet}、反光衣 ${d.no_vest}；待确认含历史 ${d.pending} 条。\n录像离线抽帧检测；线索条数不代表人数，需现场核实。统计时间 ${m.updated_at}。请优先处理逾期 ${s.overdue} 项。`;}}
  else{const r=await fetch('/api/chat/stream',{method:'POST',signal:chatAbort.signal,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({message:q,session_id:curSessId,source_id:chatSource})});if(!r.ok)throw Error((await r.json()).message);const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',answer='';for(;;){const {value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});let end;while((end=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,end);buffer=buffer.slice(end+2);const line=block.split('\n').find(x=>x.startsWith('data: '));if(!line)continue;const e=JSON.parse(line.slice(6));if(e.type==='session'){curSessId=e.session_id;localStorage.setItem(sessionKey(),curSessId);localStorage.setItem('safety_run_'+CUR_USER.id,e.run_id);}if(e.type==='status'&&!answer)out.textContent=e.message;if(e.type==='token'){answer+=e.content;out.textContent=answer;}if(e.type==='done'){el.querySelector('.message-refs').innerHTML=citationHtml(e.references)+`<button class="btn sm primary" onclick="goP6()">据此办理整改文书（双人复核）</button>`;localStorage.removeItem('safety_run_'+CUR_USER.id);}if(e.type==='error')throw Error(e.message);}$('chat').scrollTop=$('chat').scrollHeight;if(done)break;}chatSource=null;}
  if(generation!==authGeneration)return;await refreshSessions();}catch(e){if(generation!==authGeneration)return;out.textContent+='\n'+e.message+'。生成任务与历史保留，可重新加载会话恢复。';toast(e.message);}finally{if(generation===authGeneration){chatBusy=false;chatAbort=null;}}}
async function saveDraft(id){await api('/api/documents/'+id+'/save-draft','POST');toast('草稿已保存 · 待人工审核签字后生效');}
async function downloadFile(url,name){const r=await fetch(url,{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error((await r.json()).message);const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function kbLocate(id,chunk=''){go('p5');await kbDetail(id,chunk);}
async function kbDetail(id,chunk=''){const s=await api('/api/kb/sources/'+id+(chunk?'?chunk='+encodeURIComponent(chunk):''));openModal('资料详情',`<div class="frm"><b>${esc(s.name)}</b><p>${esc(s.doc_no)} · ${esc(s.status)} · 法定效力：${esc(s.legal_status)} · ${esc(s.region)}</p><p>${esc(s.parse_note)}</p><p>人工核验：${esc(s.verified_by||'尚未核验')} · ${esc(s.verified_at||'')}</p>${s.chunks.slice(0,10).map(c=>`<div class="src-card"><b>${esc(c.section)} · 原文第${c.page}页</b><p class="frm-tip">${c.citation_eligible?'可作新文书候选依据':'不满足新文书引用条件'} · ${esc(c.chunk_legal_status)} · ${esc(c.chunk_note)}</p><p style="white-space:pre-wrap">${esc(c.text)}</p><small>${esc(c.chunk_id)}</small></div>`).join('')||'<p>暂无可展示正文，不能作为文书依据。</p>'}</div>`,`<button class="btn" onclick="downloadFile('/api/kb/sources/${id}/file','原文资料')">下载原文</button><button class="btn" onclick="closeModal()">关闭</button>`);}
async function askAboutKb(id,name){chatSource=id;go('p2');await newChat();chatSource=id;await ask('《'+name+'》的核心要求是什么？');}
async function showMemory(){const m=await api('/api/memory');$('umenu').classList.remove('on');openModal('小安的记忆与背景',`<div class="frm"><p><b>短期上下文：</b>最近 ${m.recent_window} 条消息。较早对话生成可追溯摘要，刷新后保留。</p><p><b>长期记忆：</b>仅保存你明确要求记住的项目背景，按身份隔离，不作为法规依据。</p>${m.long_term.map(x=>`<div class="src-card"><p>${esc(x.value)}</p><small>来源消息 ${x.source_message_id||'手动添加'} · ${esc(x.created_at)}</small><br><button class="btn sm" onclick="forgetMemory(${x.id})">删除这条记忆</button></div>`).join('')||'<p class="muted">暂无长期记忆，可在对话中输入“记住……”</p>'}<label>明确添加项目背景</label><textarea id="memoryText" placeholder="仅填写希望跨会话保留的背景"></textarea><button class="btn primary" onclick="addMemory()">保存长期记忆</button><p>会话摘要 ${m.summaries.length} 条 · 历史会话按当前身份持久化保存。</p></div>`,'<button class="btn" onclick="closeModal()">关闭</button>');}
async function forgetMemory(id){await api('/api/memory/'+id,'DELETE');await showMemory();toast('该记忆已删除，不再参与回答');}
async function addMemory(){await api('/api/memory','POST',{value:$('memoryText').value});await showMemory();toast('已保存当前身份的长期记忆');}
let recoveringRun=null;
async function recoverRun(rid){if(recoveringRun===rid)return;recoveringRun=rid;const uid=CUR_USER.id;try{for(;;){if(!CUR_USER||CUR_USER.id!==uid)return;const r=await api('/api/task/'+rid+'/status');if(r.status==='done'){localStorage.removeItem('safety_run_'+uid);if(curSessId===r.session_id)await loadChat(curSessId);return;}if(r.status==='error'){localStorage.removeItem('safety_run_'+uid);toast(r.error||'上次生成未完成，可重新提问');return;}if(curSessId===r.session_id){let el=$('chat').querySelector('[data-recovery]');if(!el){el=appendMessage('assistant','正在恢复上次回答…');el.dataset.recovery='1';}el.querySelector('.message-text').textContent=r.answer||r.status_message;}await new Promise(resolve=>setTimeout(resolve,500));}}catch(e){localStorage.removeItem('safety_run_'+uid);}finally{recoveringRun=null;}}
let p6Hazard=null,p6Task=null,p6Timer=null,p6LoadVersion=0;
async function load_p6(){const request=++p6LoadVersion;clearTimeout(p6Timer);p6Hazard=null;p6Task=null;$('p6Work').innerHTML='<div class="card card-b empty">正在加载隐患办理记录…</div>';const data=await api('/api/hazards?filter=heavy');if(request!==p6LoadVersion)return;const hs=data.items.filter(h=>!['已销项','已闭环'].includes(h.status));if(!selectedHazard||!hs.some(h=>h.id===selectedHazard))selectedHazard=hs[0]?.id||null;const id=selectedHazard;$('p6Queue').innerHTML=hs.map(h=>`<div class="qitem ${h.id===id?'on':''}" onclick="p6Sel(${h.id})"><b>${esc(h.title)}</b>${h.is_demo?'<span class="chip amber">演示模拟</span>':''}<div class="muted" style="font-size:11px;margin-top:4px">${esc(h.responsible_team)} · ${esc(h.deadline||'期限待补充')} · ${esc(h.status)}</div></div>`).join('')||'<div class="empty">暂无待办理重轨隐患，请先在台账登记</div>';$('p6Queue').closest('.card').querySelector('.chip').textContent=hs.length+' 项';
  if(!id){$('p6Work').innerHTML='<div class="card card-b empty">暂无待办理隐患，请从右上角去台账登记</div>';return;}const h=await api('/api/hazards/'+id),tasks=await api('/api/handle/tasks?hazard_id='+id),task=tasks.length?await api('/api/handle/tasks/'+tasks[0].id):null;if(request!==p6LoadVersion||selectedHazard!==id)return;p6Hazard=h;p6Task=task;p6Render();if(p6Task&&!['pending_human','needs_input','issued','error'].includes(p6Task.status))p6Timer=setTimeout(p6Poll,500);}
async function p6Sel(id){selectedHazard=id;p6Task=null;await load_p6();}
function p6RenderOriginal(){const h=p6Hazard,t=p6Task,d=t?.document,c=d?.content||{},busy=t&&!['pending_human','needs_input','issued','error'].includes(t.status);const stages=[['Agent A 检索起草',t?.steps.some(s=>s.name.startsWith('Agent A'))],['Agent B 独立复核',t?.steps.some(s=>s.name==='Agent B 独立复核')],['人工确认签发并入账',d?.status==='issued']];const conclusion=t?.status==='pending_human'?'AI 检查未发现阻断问题，待人工确认':t?.status==='needs_input'?'依据或必填信息不足，请补充后重新办理':t?.status==='issued'?'文书已人工签发 · '+h.status:t?.status==='error'?t.error:busy?'办理中 · '+(t.steps.at(-1)?.name||'已受理'):'待开始';
  $('p6Work').innerHTML=`<div class="case-card"><div class="cc-head">🛡️ ${esc(h.title)}<span class="cc-st">${esc(conclusion)}</span><span class="cc-kv">${h.is_demo?'【演示模拟】 ':''}${esc(h.code)} · ${esc(h.source)} · ${esc(h.status)}</span></div><div class="cc-tl">${stages.map(([label,done])=>`<div class="cc-step"><span class="s-ic">${done?'✓':'○'}</span><div><b>${label}</b></div><span class="s-st ${done?'step-ok':''}">${done?'已记录':'等待'}</span></div>`).join('')}</div><details class="cc-d" ${!t||t.status==='needs_input'?'open':''}><summary>办理信息 · 人工补充</summary><div class="cc-body frm"><div class="row2"><div><label>责任班组 *</label><input id="p6Team" value="${esc(c.responsible_team??h.responsible_team)}" ${busy?'disabled':''}></div><div><label>责任人 *</label><input id="p6Person" value="${esc(c.responsible_person??h.responsible_person)}" ${busy?'disabled':''}></div></div><label>整改期限 *</label><input type="date" id="p6Deadline" value="${esc(c.deadline??h.deadline)}" ${busy?'disabled':''}><label>安全员补充说明</label><textarea id="p6Note" ${busy?'disabled':''}>${esc(t?.note||'')}</textarea><p class="frm-tip">未提供的事实不由 AI 编造。补充信息随草稿复核，签发后写回原隐患。</p></div></details><details class="cc-d" ${d?'open':''}><summary>整改文书 ${d?'v'+d.draft_version:'待生成'}</summary><div class="cc-body">${d?`<p><span class="chip ${d.status==='issued'?'green':'amber'}">${d.status==='issued'?'已人工签发':'草稿 · 待人工确认'}</span> ${esc(d.doc_no||'签发后生成唯一编号')}</p><p>责任班组：${esc(c.responsible_team||'待填写')} · 责任人：${esc(c.responsible_person||'待填写')} · 期限：${esc(c.deadline||'待填写')}</p><pre style="white-space:pre-wrap;font-family:inherit">${esc(c.body||'依据不足，待补资料')}</pre>${c.mode==='offline'?'<p class="frm-tip">当前为离线兜底结果 · 两角色为规则和模板辅助，待人工核对。</p>':''}`:'Agent A 起草后在此展示真实草稿'}</div></details><details class="cc-d"><summary>规范依据 · 检索出处</summary><div class="cc-body">${(c.evidence||[]).map(e=>`<div class="src-card"><b>${esc(e.name)} ${esc(e.doc_no)} ${esc(e.section)}</b><p>${esc(e.text)}</p><button class="btn sm" onclick="kbLocate(${e.source_id},'${e.chunk_id}')">在知识库中定位 ↗</button></div>`).join('')||'尚无可用依据，不允许签发。'}</div></details><details class="cc-d"><summary>复核意见 · Agent B 与规则校验</summary><div class="cc-body">${(d?.reviews||[]).map(r=>{const x=JSON.parse(r.result_json);return `<p><b>第${r.round}轮 ${esc(r.reviewer)}</b> · ${esc(x.model?.mode||'rules')}</p>${x.issues.length?x.issues.map(p=>`<div class="src-card"><b>${p.block?'阻断':'建议'} · ${esc(p.type)} · ${esc(p.location)}</b><p>依据：${esc(p.basis)}</p><p>修订要求：${esc(p.fix)}</p></div>`).join(''):'<p>AI 检查未发现阻断问题，待人工确认</p>'}`;}).join('')||'等待复核'}</div></details><details class="cc-d"><summary>办理记录 · 全程留痕与交接</summary><div class="cc-body">${(t?.steps||[]).map(s=>`<details><summary>${esc(s.time)} · ${esc(s.name)}</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify(s.payload,null,2))}</pre></details>`).join('')||'尚未开始'}</div></details><div class="cc-act" style="flex-wrap:wrap">${busy?'<span>⏳ 正在执行真实办理任务，可离开页面，任务会继续并保存。</span>':d?.status==='issued'?`<span>已签发 ${esc(d.doc_no)} · ${esc(h.status)}</span><button class="btn primary" onclick="goLedger(${h.id})">前往隐患台账</button><span class="frm-tip">整改反馈与现场复查在台账完成。</span>`:`<button class="btn primary" onclick="p6Start()">${t?'补充后重新办理':'▶ 开始智能办理'}</button>${t?.status==='pending_human'?'<button class="btn primary" onclick="p6Sign()">确认签发并存入台账</button>':''}`}${d?`<button class="btn" onclick="saveDraft(${d.id})" ${d.status==='issued'?'disabled':''}>保存为草稿</button><button class="btn" onclick="p6Copy()">复制</button><button class="btn" onclick="downloadFile('/api/documents/${d.id}/export','整改通知单-${d.id}.docx')">导出 Word</button>`:''}</div></div>`;}
function p6Render(){p6RenderOriginal();if(!canOperate()){const panel=$('p6Work');panel.querySelectorAll('input,textarea').forEach(e=>e.disabled=true);panel.querySelectorAll('button').forEach(b=>{if(/p6Start|p6Sign|saveDraft/.test(b.getAttribute('onclick')||''))b.hidden=true;});panel.querySelector('.cc-act')?.insertAdjacentHTML('afterbegin','<span class="frm-tip">总监可查看办理与引用记录；签发和现场复查由安全员执行。</span>');}}
async function p6Start(){if(!p6Hazard)return;const button=$('p6Work').querySelector('[onclick="p6Start()"]');if(button?.disabled)return;if(button)button.disabled=true;const id=p6Hazard.id,request=++p6LoadVersion,body={hazard_id:id,note:$('p6Note').value,responsible_team:$('p6Team').value,responsible_person:$('p6Person').value,deadline:$('p6Deadline').value||null};clearTimeout(p6Timer);try{const result=await api('/api/handle/tasks','POST',body),task=await api('/api/handle/tasks/'+result.task_id);if(request!==p6LoadVersion||selectedHazard!==id)return;p6Task=task;p6Render();p6Timer=setTimeout(p6Poll,300);}finally{if(button?.isConnected)button.disabled=false;}}
async function p6Poll(){if(!$('p6').classList.contains('active')||!p6Task)return;const id=p6Task.id;const t=await api('/api/handle/tasks/'+id);if(p6Task?.id!==id)return;p6Task=t;p6Render();if(!['pending_human','needs_input','issued','error'].includes(t.status))p6Timer=setTimeout(p6Poll,500);}
function p6Sign(){const d=p6Task.document;openModal('人工确认签发',`<p>请核对隐患事实、适用条款、责任人及期限。</p><p>${esc(d.content.hazard_title)}</p><p>责任人：${esc(d.content.responsible_person)} · 期限：${esc(d.content.deadline)}</p><p class="frm-tip">确认后以当前登录身份签发，关联原隐患并全程留痕。</p>`,`<button class="btn" onclick="closeModal()">返回核对</button><button class="btn primary" onclick="issuePendingDocument(${d.id})">我已核对，确认签发</button>`);}
async function issuePendingDocument(id){const r=await api('/api/documents/'+id+'/issue','POST',{confirmed:true});closeModal();await load_p6();toast('已人工签发 '+r.doc_no+' · 已关联原隐患');}
async function p6Copy(){const c=p6Task?.document?.content;if(!c)return;await navigator.clipboard.writeText([c.hazard_title,c.responsible_team,c.responsible_person,c.deadline,c.body].filter(Boolean).join('\n'));toast('文书内容已复制');}
async function goLedger(id){selectedHazard=id;curF='heavy';go('p3');await load_p3();document.querySelector('#hzBody tr[data-hazard="'+id+'"]')?.scrollIntoView({block:'center'});}
function goLedgerRegister(){go('p3');openHzModal();}
let HZ=[];
const sourceName=s=>({manual:'人工巡查',ai_monitor:'AI 监控',document:'文书登记'}[s]||s);
const canOperate=()=>CUR_USER&&['专职安全员','安全员'].includes(CUR_USER.role);
function rowActions(h){let html='';if(canOperate()){
  if(h.track==='heavy'&&!['已销项','已闭环'].includes(h.status))html+=`<button class="btn sm" onclick="event.stopPropagation();goP6(${h.id})">办理文书</button> `;
  if(h.status==='待确认')html+=`<button class="btn sm primary" onclick="event.stopPropagation();hazardAction(${h.id},'confirm')">现场确认</button> `;
  if(h.status==='待整改')html+=`<button class="btn sm" onclick="event.stopPropagation();hazardAction(${h.id},'start_rectify')">开始整改</button> `;
  if(h.status==='整改中')html+=`<button class="btn sm primary" onclick="event.stopPropagation();rectifyModal(${h.id})">${h.track==='light'?'纠正教育并闭环':'登记整改反馈'}</button> `;
  if(h.status==='待复查')html+=`<button class="btn sm primary" onclick="event.stopPropagation();openReview(${h.id})">复查销项</button> `;
  }if(h.track==='heavy'&&!['已销项','已闭环'].includes(h.status))html+=`<button class="btn sm" onclick="event.stopPropagation();hazardAction(${h.id},'urge','安全员在系统内记录催办')">催办</button>`;
  return html||`<button class="btn sm" onclick="event.stopPropagation();viewHazard(${h.id})">查看档案</button>`;}
async function load_p3(){const data=await api('/api/hazards?filter='+curF);HZ=data.items;document.querySelector('#p3 .page-head button.primary').hidden=!canOperate();document.querySelectorAll('#p3 .tab').forEach(t=>{t.classList.toggle('active',t.dataset.f===curF);t.querySelector('.n').textContent=data.counts[t.dataset.f]||0;});document.querySelector('[data-page=p3] .badge').textContent=data.counts.over;$('hzBody').innerHTML=HZ.map(h=>`<tr data-hazard="${h.id}" style="cursor:pointer" onclick="viewHazard(${h.id})"><td style="font-weight:600">${esc(h.title)}<div class="muted" style="font-size:10px">${esc(h.code)} ${h.is_demo?'<span class="chip amber">演示模拟</span>':''}</div></td><td><span class="chip ${h.track==='light'?'blue':'orange'}">${h.track==='light'?'即查即改 · 轻轨':'限期整改 · 重轨'}</span></td><td>${esc(h.responsible_team||'待补充')}<div class="muted" style="font-size:11px">${esc(h.responsible_person||'责任人待补充')}</div></td><td class="mono">${esc(h.deadline||'当场')}</td><td><span class="chip ${h.overdue?'red':h.status==='待复查'?'amber':['已销项','已闭环'].includes(h.status)?'green':'blue'}">${esc(h.status)}${h.overdue?' · 逾期'+h.overdue_days+'天':''}</span></td><td style="font-size:12px">${sourceName(h.source)}</td><td><div style="display:flex;gap:5px;flex-wrap:wrap">${rowActions(h)}</div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">该分类下暂无隐患</div></td></tr>';}
function filterHz(f,el){curF=f;load_p3();}
function renderHz(){return load_p3();}
function renderHzTabs(){return load_p3();}
async function viewHazard(id){const h=await api('/api/hazards/'+id);selectedHazard=id;for(const a of h.attachments)attachmentNames.set(a.id,a.original_name);openModal('隐患详情与证据链',`<div class="frm"><h3>${esc(h.title)}</h3><p>${h.is_demo?'<b class="chip amber">演示模拟案例</b> ':''}${esc(h.code)} · ${esc(h.status)} · ${esc(h.location)}</p><p>责任方：${esc(h.responsible_team||'待填')} · ${esc(h.responsible_person||'待填')} · 期限：${esc(h.deadline||'当场')}</p><p>发现来源：${sourceName(h.source)} · 现场确认：${esc(h.confirmed_at||'待确认')}</p><h4>班组整改反馈</h4>${hazardFeedbackHtml(h)}<h4>整改证据附件</h4>${rectifyEvidenceHtml(h)}<p>复查意见：${esc(h.review_note||'尚未复查')}</p><b>关联文书</b>${h.documents.map(d=>`<p><button class="btn sm" onclick="showDocument(${d.id})">${esc(d.doc_no||d.title)} · ${esc(d.status)}</button></p>`).join('')||'<p>尚无关联文书</p>'}<b>证据附件</b>${h.attachments.map(a=>`<p><button class="btn sm" onclick="downloadEvidence(${a.id})">${esc(a.original_name)} · ${esc(a.kind)}</button></p>`).join('')||'<p>暂无附件</p>'}<b>全程留痕</b>${h.events.map(e=>`<details><summary>${esc(e.created_at)} · 记录人 ${esc(e.actor_name||e.actor||'未记录')} · ${esc(hazardEventLabel(e.action,h.track))}</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(e.detail)}</pre></details>`).join('')}</div>`,`<button class="btn" onclick="askHazardClause(${id})">查相关条款</button>${canOperate()&&!['已销项','已闭环'].includes(h.status)?`<button class="btn" onclick="uploadEvidenceModal(${id})">上传现场证据</button>`:''}<button class="btn" onclick="viewDoc(${id})">查看文书</button><button class="btn" onclick="closeModal()">关闭</button>`);hydrateRectifyEvidence(h);}
async function viewDoc(id){const h=await api('/api/hazards/'+id);if(!h.documents.length)return toast('尚无文书，请在隐患办理页起草并人工签发');await showDocument(h.documents[0].id);}
async function showDocument(id){const d=await api('/api/documents/'+id);openModal('关联文书',`<div class="doc-box"><div class="dt">${esc(d.title)}</div><p>${esc(d.doc_no||'草稿 · 尚未签发')} · ${esc(d.status)}</p><p>责任班组：${esc(d.content.responsible_team||'待填写')} · 责任人：${esc(d.content.responsible_person||'待填写')}</p><pre style="white-space:pre-wrap;font-family:inherit">${esc(d.content.body||'')}</pre>${citationHtml(d.content.evidence||[])}</div>`,`<button class="btn" onclick="downloadFile('/api/documents/${id}/export','文书-${id}.docx')">导出 Word</button><button class="btn" onclick="closeModal()">关闭</button>`);}
async function askHazardClause(id){const h=await api('/api/hazards/'+id);closeModal();go('p2');await newChat();await ask(h.title+'有什么规范要求？');}
let hazardPreviewUrls=[],hazardEvidenceRevision=0;
function clearHazardPreviews(){hazardEvidenceRevision++;hazardPreviewUrls.forEach(u=>URL.revokeObjectURL(u));hazardPreviewUrls=[];}
function hazardEventLabel(action,track){return ({register:'隐患登记',prepare_demo_case:'新建演示模拟案例',submit_rectify:track==='heavy'?'安全员登记整改反馈':'现场纠正教育并闭环',review_close:'现场复查合格并销项',review_return:'现场复查不合格，退回整改',upload_evidence:'上传证据',issue_document:'人工确认签发'})[action]||action;}
function hazardFeedbackHtml(h){return (h.feedbacks||[]).map((f,i)=>`<div class="src-card" data-feedback="${f.id||'legacy'}"><b>${f.is_simulated?'【演示模拟】 ':''}${f.feedback_source==='legacy'?'历史整改记录（原系统未区分反馈来源）':f.feedback_source==='demo_simulation'?'安全员登记模拟班组回复':'安全员代录班组反馈'}</b><p>责任班组：${esc(f.responsible_team||'未记录')}<br>班组提供人：${esc(f.provided_by||'未记录')} · 班组反馈时间：${esc(f.provided_at||'未记录')}<br>登记人：${esc(f.recorded_by_name||'未记录')} · 登记时间：${esc(f.recorded_at||'未记录')}</p><p style="white-space:pre-wrap">${esc(f.content)}</p></div>`).join('')||'<p class="muted">暂无已登记的整改反馈；历史记录缺失时请现场核实，不推定已整改。</p>';}
function rectifyEvidenceHtml(h){const files=(h.attachments||[]).filter(a=>a.kind==='rectify');return `<div id="rectifyEvidenceList">${files.map(a=>{attachmentNames.set(a.id,a.original_name);return `<div class="src-card"><button class="btn sm" onclick="downloadEvidence(${a.id})">下载 ${esc(a.original_name)}</button><p class="frm-tip">登记人 ${esc(a.recorded_by_name||'未记录')} · ${esc(a.created_at||'时间未记录')}</p>${a.available===false?'<p>证据文件缺失</p>':a.is_image?`<img id="rectifyEvidence${a.id}" alt="整改后证据：${esc(a.original_name)}" style="display:block;max-width:100%;max-height:220px;object-fit:contain"><span id="rectifyEvidenceStatus${a.id}" class="frm-tip">正在读取图片</span>`:''}</div>`;}).join('')||'<p class="muted">暂无整改证据</p>'}</div>`;}
async function hydrateRectifyEvidence(h){const revision=hazardEvidenceRevision,identity=token;for(const a of (h.attachments||[]).filter(x=>x.kind==='rectify'&&x.is_image&&x.available!==false)){try{const r=await fetch('/api/hazards/attachments/'+a.id,{headers:{Authorization:'Bearer '+identity}});if(!r.ok)throw Error('整改图片不可读取');const blob=await r.blob();if(revision!==hazardEvidenceRevision||token!==identity)return;const u=URL.createObjectURL(blob);hazardPreviewUrls.push(u);const img=$('rectifyEvidence'+a.id);if(img){img.src=u;$('rectifyEvidenceStatus'+a.id).textContent='整改后图片预览';}}catch(e){if(revision===hazardEvidenceRevision&&$('rectifyEvidenceStatus'+a.id))$('rectifyEvidenceStatus'+a.id).textContent=e.message;}}}
async function rectifyModal(id){const h=await api('/api/hazards/'+id);if(h.track==='light'){openModal('记录现场纠正与教育',`<div class="frm"><label>实际纠正、教育情况 *</label><textarea id="rectifyNote" placeholder="据实填写当场纠正与教育经过"></textarea></div>`,`<button class="btn" onclick="uploadEvidenceModal(${id})">上传证据</button><button class="btn primary" onclick="hazardAction(${id},'submit_rectify',$('rectifyNote').value,${h.version})">记录纠正并闭环</button>`);return;}if(h.status!=='整改中')return toast('只有整改中隐患可以登记整改反馈');const preset=h.demo_feedback&&!h.demo_feedback.received?h.demo_feedback:null;openModal('登记整改反馈',`<div class="frm"><h3>${esc(h.title)}</h3><p>${h.is_demo?'<b>【演示模拟案例】</b> ':''}责任班组：${esc(h.responsible_team||'待填写')}</p><p class="frm-tip">责任班组负责实际整改；安全员负责接收、代录反馈及后续现场复查。登记时间由系统记录。</p>${preset?`<h4>待接收的模拟班组回复</h4><div class="src-card"><b>演示模拟数据，不代表真实班组提交</b><p>反馈来源：预置模拟回复 · ${esc(preset.feedback_team)}<br>班组实际提交人及时间：未记录<br>模拟准备时间：${esc(preset.prepared_at)}</p><p style="white-space:pre-wrap">${esc(preset.feedback_content)}</p></div>`:`<label>反馈所属责任班组 *</label><input id="feedbackTeam" value="${esc(h.responsible_team||'')}" placeholder="据实填写责任班组"><label>班组提供人（可选）</label><input id="feedbackProvider" placeholder="未知时留空，不代造班组账号"><label>班组反馈时间（可选）</label><input id="feedbackAt" type="datetime-local"><label>班组反馈内容 *</label><textarea id="rectifyNote" placeholder="代录班组提供的实际信息，不代表安全员负责实际整改"></textarea>`}<h4>整改证据附件</h4>${rectifyEvidenceHtml(h)}<label>补充整改后证据（可选）</label><input id="feedbackEvidenceFile" type="file" accept=".png,.jpg,.jpeg,.pdf"><p class="frm-tip">未提供文件时不会生成或假定存在整改照片。收到反馈后仅转为待复查，不自动销项。</p></div>`,`<button class="btn" onclick="closeModal()">取消</button><button id="receiveFeedbackButton" class="btn primary" onclick="receiveFeedback(${id},${h.version},'${preset?'demo_simulation':'safety_officer_recorded'}')">${preset?'确认接收模拟反馈并登记':'确认接收并登记反馈'}</button>`);hydrateRectifyEvidence(h);}
async function receiveFeedback(id,version,source){const button=$('receiveFeedbackButton');if(button.disabled)return;button.disabled=true;try{const body={action:'submit_rectify',version,feedback_source:source,note:source==='demo_simulation'?'':$('rectifyNote').value.trim()};if(source!=='demo_simulation'){body.feedback_team=$('feedbackTeam').value.trim();body.feedback_provider=$('feedbackProvider').value.trim();body.feedback_at=$('feedbackAt').value?new Date($('feedbackAt').value).toISOString():null;if(!body.feedback_team||!body.note)throw Error('请填写反馈班组和班组反馈内容');}const file=$('feedbackEvidenceFile').files[0];if(file){const form=new FormData();form.append('file',file);form.append('kind','rectify');await api('/api/hazards/'+id+'/attachments','POST',form);}await api('/api/hazards/'+id+'/actions','POST',body);closeModal();await load_p3();await load_p1();toast('安全员已登记收到的反馈，状态为待复查，尚未现场复查销项');}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}}
function prepareDemoModal(){openModal('准备新的演示案例','<div class="frm"><p>新建“3#楼东侧基坑临边防护缺失，未设防护栏杆”演示记录，并准备明确标注的模拟班组回复。</p><p>旧隐患、已销项档案及历史事件全部保留。创建后请从隐患办理启动双 Agent，完成签发后再到台账登记模拟反馈。</p></div>','<button class="btn" onclick="closeModal()">取消</button><button id="prepareDemoButton" class="btn primary" onclick="prepareDemoCase()">确认新建演示记录</button>');}
async function prepareDemoCase(){const button=$('prepareDemoButton');if(button.disabled)return;button.disabled=true;try{const h=await api('/api/hazards/demo-cases','POST',{confirmed:true});selectedHazard=h.id;closeModal();curF='all';await load_p3();toast('已新建 '+h.code+'，原档案保留');goP6(h.id);}catch(e){toast(e.message);}finally{if(button.isConnected)button.disabled=false;}}
const attachmentNames=new Map();
function downloadEvidence(id){return downloadFile('/api/hazards/attachments/'+id,attachmentNames.get(id)||'现场证据');}
function uploadEvidenceModal(id){openModal('上传现场证据',`<div class="frm"><label>证据类型</label><select id="evidenceKind"><option value="before">发现证据</option><option value="rectify">整改后证据</option><option value="review">现场复查证据</option></select><label>PNG / JPEG / PDF，最大10MB</label><input id="evidenceFile" type="file" accept=".png,.jpg,.jpeg,.pdf"></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="uploadEvidence(${id})">保存附件并留痕</button>`);}
async function uploadEvidence(id){const file=$('evidenceFile').files[0];if(!file)return toast('请选择证据文件');const form=new FormData();form.append('file',file);form.append('kind',$('evidenceKind').value);await api('/api/hazards/'+id+'/attachments','POST',form);await viewHazard(id);toast('证据已保存并关联隐患');}
async function exportHz(){await downloadFile('/api/hazards/export?filter='+curF,'隐患迎检台账-'+new Date().toISOString().slice(0,10)+'.csv');toast('已导出当前筛选结果，含留痕、引用及附件索引');}
let CAMS=[],curCam=2,patrolT=null,monitorFilter='pending',monitorRun=null,monitorTimer=null,imageUrls=[];
let monitorRoutePromise=null,monitorLatest=[],monitorView='overlay',monitorFrames={},monitorFrameUrl=null,monitorFrameId=null,monitorImageSeq=0,monitorStarting=false,monitorRefreshBusy=false,monitorFingerprint='';
let monitorPlaybackCache={},monitorPlayback=null,monitorPresentedTime=0,monitorOverlayFrame=-1;
async function monitorOrigin(){
  if(!monitorRoutePromise)monitorRoutePromise=(async()=>{const r=await fetch('/static/monitor-runtime.local.json',{cache:'no-store'});if(r.status===404)return '';if(!r.ok)throw Error('监控连接配置无法读取');const c=await r.json();if(String(c.app_port)!==location.port||!c.api_origin)return '';const u=new URL(c.api_origin);if(!['127.0.0.1','localhost'].includes(u.hostname)||u.protocol!=='http:')throw Error('监控连接配置无效');return u.origin;})().catch(e=>{monitorRoutePromise=null;throw e;});
  return monitorRoutePromise;
}
function monitorGroups(m){return {real:m.real||{violations:0,no_helmet:0,pending:0,pending_today:0,confirmed_today:0,dismissed_today:0,trend:[]},demo:m.demo||{violations:m.violations,no_helmet:m.no_helmet,no_vest:m.no_vest,pending:m.pending}};}
function monitorCountText(m){const {real:r,demo:d}=monitorGroups(m);return `<p>今日真实 YOLO 安全帽线索 <b data-real-count="${r.no_helmet}">${r.no_helmet}</b> 条 · 待确认 ${r.pending_today} · 已确认 ${r.confirmed_today} · 已驳回 ${r.dismissed_today}<br>真实待确认含历史积压 ${r.pending} 条</p><p>演示数据单列：今日未驳回 ${d.violations} 条（安全帽 ${d.no_helmet} / 反光衣 ${d.no_vest}）· 待确认含历史 ${d.pending} 条<br>线索数不是现场人数；检测时间不是录像拍摄时间。</p>`;}
function renderHomeMonitor(m){if(!m){$('p1').querySelector('.grid > .card:nth-child(2) .card-b').innerHTML='<div class="empty">监控统计暂不可用，请检查独立监控服务。其他业务仍可使用。</div>';return;}const {real:r}=monitorGroups(m);const attendance=m.data_mode==='demo'?`${m.on_site} 人 · 演示数据，未接门禁`:'未接入有效人数来源';$('p1').querySelector('.grid > .card:nth-child(2) .card-b').innerHTML=`<div style="font-size:13px;line-height:1.8;color:#182233"><b>真实 YOLO 安全帽线索 · 今日</b><div style="font-size:30px;font-weight:800;color:var(--amber)" data-home-real="${r.no_helmet}">${r.no_helmet} 条</div>${monitorCountText(m)}<p>在场人数：${esc(attendance)}</p><div style="font-size:11px;color:#687386">统计自动刷新 · ${esc(m.updated_at||'')}<br>待确认及已确认计入，驳回剔除；录像离线抽帧。</div></div><button class="btn primary" style="width:100%;justify-content:center;margin-top:14px" onclick="go('p4');setMode('board')">进入视察大屏</button>`;}
function renderMonitorStats(m){const {real:r,demo:d}=monitorGroups(m),stats=$('board').querySelectorAll('.bstat');stats[0].innerHTML=`<div class="bl">在场人数 · ${m.data_mode==='demo'?'演示数据':'尚未接入'}</div><div class="bn">${m.data_mode==='demo'?m.on_site:'—'}<small> 人</small></div><div style="font-size:11px;color:#B5C2D3">尚未接入门禁；不使用头部目标推算</div>`;stats[1].innerHTML=`<div class="bl">今日真实安全帽线索</div><div class="bn" data-board-real="${r.no_helmet}">${r.no_helmet}<small> 条</small></div><div style="font-size:11px;color:#B5C2D3">待确认 ${r.pending_today} · 已确认 ${r.confirmed_today} · 驳回 ${r.dismissed_today}</div>`;stats[2].innerHTML=`<div class="bl">演示线索 · 与真实数据分列</div><div class="bn">${d.violations}<small> 条</small></div><div style="font-size:11px;color:#B5C2D3">安全帽 ${d.no_helmet} · 反光衣 ${d.no_vest}（未训练）</div>`;
  const trend=r.trend;$('bars').innerHTML=trend.map(x=>`<div class="bar-col"><div class="bar" style="height:${x.count/Math.max(1,...trend.map(t=>t.count))*100}%">${x.count?'<span class="bv">'+x.count+'</span>':''}</div><div class="bl2">${x.hour}时</div></div>`).join('');$('board').querySelector('.chart > div:last-child').textContent=`按本次检测执行时间统计；真实线索待确认及已确认计入，已驳回剔除。演示数据不计入此图。更新 ${m.updated_at||''}；待确认含历史积压 ${r.pending} 条。`;
  renderHomeMonitor(m);
}
async function load_p4(){const [m,snaps]=await Promise.all([api('/api/monitor/overview'),api('/api/monitor/snapshots?status='+monitorFilter)]);CAMS=m.cameras;renderMonitorStats(m);
  const cards=document.querySelectorAll('#normal > .grid > .card');cards[0].querySelector('.chip').textContent=m.pending+' 条待确认（含演示）';cards[0].querySelector('.snap-list').innerHTML=`<div style="display:flex;gap:8px;margin-bottom:12px;align-items:center"><select onchange="monitorFilter=this.value;load_p4()">${[['pending','待确认'],['confirmed','已确认'],['dismissed','已驳回'],['all','全部线索']].map(([v,n])=>`<option value="${v}" ${v===monitorFilter?'selected':''}>${n}</option>`).join('')}</select><button class="btn sm primary" data-detect onclick="runDetection()" ${canOperate()?'':'disabled'}>运行当前摄像头片段检测</button><span id="monitorRunStatus" class="muted" style="font-size:11px"></span></div>`+snaps.map(s=>`<div class="snap" data-snapshot="${s.id}" ${s.id===selectedSnapshot?'style="background:#FFF4E6"':''}><div class="thumb">${s.image_path?`<img id="snapImg${s.id}" alt="真实安全帽检测抓拍" style="width:64px;height:64px;object-fit:cover;cursor:pointer" onclick="viewSnapshotImage(${s.id})">`:'<span class="pp">👷</span>'}</div><div class="sb"><div style="font-size:13px;font-weight:600">${esc(s.category)} · ${esc(s.location)}</div><div class="muted" style="font-size:11px">${esc(s.captured_at.slice(0,10)+' '+s.captured_at.slice(11,19))} · ${s.camera_id} · ${s.data_mode==='yolo'&&Number.isFinite(s.confidence)?'模型置信度 '+(s.confidence*100).toFixed(1)+'%':'未提供真实模型置信度'}</div><div class="muted" style="font-size:11px">${s.data_mode==='yolo'?'真实YOLO检测 · 待现场核实':'演示线索'} · ${esc(s.status)}</div></div>${s.status==='pending'&&canOperate()?`<div style="display:flex;gap:5px;flex-wrap:wrap"><button class="btn sm" onclick="confirmSnap(${s.id})">确认为隐患</button><button class="btn sm" onclick="dismissSnap(${s.id})">驳回误报</button></div>`:s.hazard_id?`<button class="btn sm" onclick="focusHazard(${s.hazard_id})">查看轻轨记录</button>`:'<span class="muted">已驳回</span>'}</div>`).join('')+(snaps.length?'':'<div class="empty">该状态下暂无线索</div>');
  cards[1].querySelector('.chip').textContent=m.pending+' 条待确认（含演示）';cards[1].querySelector('.card-b').innerHTML=monitorCountText(m)+'<p>真实检测与演示数据分列；线索须现场核实，未驳回不代表已经确认。</p>';
  cards[2].querySelector('.card-b').innerHTML='<p><b>实际模型类别（2 类）</b><br>佩戴安全帽 / 未佩戴安全帽，均为头部目标。反光衣为演示数据（模型待训练）。</p><p><b>历史训练验证集指标</b><br>mAP50 = 0.761 · P = 0.827 · R = 0.698<br>不等于本次施工现场准确率，不由头部目标推算全场人数。</p><p><b>AI 是线索，人是裁判</b><br>不作为执法/追责依据；经安全员现场确认后才计入台账。</p><p>线索条数和抽样头部目标数均不代表全场人数；不做人脸识别与身份关联。</p>';
  imageUrls.forEach(u=>URL.revokeObjectURL(u));imageUrls=[];for(const s of snaps.filter(s=>s.image_path)){const r=await fetch((await monitorOrigin())+'/api/monitor/snapshots/'+s.id+'/image',{headers:{Authorization:'Bearer '+token}});if(r.ok){const u=URL.createObjectURL(await r.blob());imageUrls.push(u);const img=$('snapImg'+s.id);if(img)img.src=u;}}

  if(!$('vwVideo').getAttribute('src')?.endsWith(CAMS[curCam].file))switchCam(curCam);await refreshMonitorRuns();}
function renderThumbs(){$('vwThumbs').innerHTML=CAMS.map((c,i)=>{const entry=monitorLatest.find(x=>x.camera_id===c.id),r=entry?.latest,done=entry?.completed;return `<div class="vw-thumb ${i===curCam?'on':''}" onclick="switchCam(${i})"><video src="${c.url}" muted playsinline preload="metadata"></video><div class="vw-tag">${c.id}</div><div class="vw-live">本地录像</div><div class="cam-result">${!c.available?'录像缺失':r?.status==='running'?'YOLO 检测中':r?.status==='queued'?'等待串行检测':r?.status==='error'?'检测失败':done?'真实检测 '+done.result.frames.length+' 帧':c.playback_prepared?'离线逐帧回放已准备':'尚未采集线索'}</div></div>`;}).join('');}
function switchCam(i){if(!CAMS[i])return;curCam=i;monitorPlayback=null;monitorOverlayFrame=-1;$('vwDetect').innerHTML='';const c=CAMS[i],v=$('vwVideo');if(monitorView!=='overlay'&&!v.getAttribute('src')?.endsWith(c.file))v.src=c.url;$('vwTag').textContent=c.id+' · '+c.location;renderThumbs();renderMonitorResult().catch(e=>toast(e.message));}
function setMonitorView(mode){monitorView=mode;renderMonitorResult().catch(e=>toast(e.message));}
function togglePatrol(){if(patrolT){clearInterval(patrolT);patrolT=null;$('patrolBtn').textContent='▶ 自动轮巡';}else{patrolT=setInterval(()=>switchCam((curCam+1)%CAMS.length),6000);$('patrolBtn').textContent='⏸ 停止轮巡';}}
