async function snapshotAction(id,action){const result=await api('/api/monitor/snapshots/'+id+'/'+action,'POST',{note:$('snapshotNote').value});closeModal();await load_p4();await load_p1();toast(action==='confirm'?'现场确认后已创建轻轨隐患':'已驳回并留痕，未创建隐患');}
async function viewSnapshotImage(id){const r=await fetch((await monitorOrigin())+'/api/monitor/snapshots/'+id+'/image',{headers:{Authorization:'Bearer '+token}});if(!r.ok)return toast('该演示线索没有真实图片');const u=URL.createObjectURL(await r.blob());imageUrls.push(u);openModal('真实检测抓拍',`<img src="${u}" style="width:100%"><p class="frm-tip">本地视频检测结果；是否构成现场隐患仍须人工核实。</p>`,'<button class="btn" onclick="closeModal()">关闭</button>');}

async function runDetection(all=false){
  if(!CAMS.length||monitorStarting||monitorLatest.some(x=>['queued','running'].includes(x.latest?.status)))return toast('已有串行检测任务，请等待完成');
  monitorStarting=true;updateMonitorRunStatus();
  try{const r=await api(all?'/api/monitor/detect-all':'/api/monitor/detect','POST',all?{max_frames:8,confidence:Number($('monitorConfidence').value)}:{camera_id:CAMS[curCam].id,max_frames:8,confidence:Number($('monitorConfidence').value)});monitorRun=all?r.runs[0].id:r.id;monitorView='result';toast(all?'四路录像按顺序执行真实 YOLO 检测':'已启动本地录像真实 YOLO 检测');await refreshMonitorRuns();}
  catch(e){toast(e.message||'检测服务不可用，请检查本地监控服务');}
  finally{monitorStarting=false;updateMonitorRunStatus();}
}
function updateMonitorRunStatus(){const active=monitorLatest.filter(x=>['queued','running'].includes(x.latest?.status)),text=active.length?active.map(x=>x.camera_id+' '+(x.latest.status==='queued'?'排队':'检测中 '+(x.latest.result.frames?.length||0)+' 帧')).join(' · '):monitorStarting?'正在提交检测任务…':'四路可独立检测，也可串行检测全部；非实时推流';for(const id of ['boardRunStatus','monitorRunStatus'])if($(id))$(id).textContent=text;document.querySelectorAll('[data-detect]').forEach(b=>b.disabled=!canOperate()||monitorStarting||active.length>0);}
async function refreshMonitorRuns(){const previous=monitorLatest;monitorLatest=await api('/api/monitor/latest');const completed=monitorLatest.some(x=>x.latest?.status==='done'&&previous.some(y=>y.camera_id===x.camera_id&&['queued','running'].includes(y.latest?.status)));if(completed)monitorView='result';renderThumbs();await renderMonitorResult();updateMonitorRunStatus();clearTimeout(monitorTimer);if(monitorLatest.some(x=>['queued','running'].includes(x.latest?.status)))monitorTimer=setTimeout(()=>pollMonitorRun().catch(e=>{toast(e.message);monitorTimer=setTimeout(()=>pollMonitorRun().catch(()=>{}),5000);}),1000);else monitorRun=null;}
async function pollMonitorRun(){if(!CUR_USER)return;const before=monitorLatest.map(x=>x.latest?.status).join();await refreshMonitorRuns();if(before!==monitorLatest.map(x=>x.latest?.status).join()){await load_p4();await load_p1();}}
setInterval(async()=>{if(!CUR_USER||document.hidden||monitorRefreshBusy)return;monitorRefreshBusy=true;try{if($('p1').classList.contains('active'))await load_p1();if($('p4').classList.contains('active')){const m=await api('/api/monitor/overview');renderMonitorStats(m);const fingerprint=JSON.stringify([m.real,m.demo,m.pending]);if(fingerprint!==monitorFingerprint){monitorFingerprint=fingerprint;if(!$('mask').classList.contains('on'))await load_p4();}else await refreshMonitorRuns();}}catch(e){if($('p4').classList.contains('active'))$('boardRunStatus').textContent='刷新失败：'+(e.message||'监控服务不可用');}finally{monitorRefreshBusy=false;}},5000);
