async function load_p5(){const request=++kbRequest;const d=await api('/api/kb/sources?'+new URLSearchParams({type:kbType,status:kbStatus,keyword:$('kbQ').value,sort:kbSort}));if(request!==kbRequest)return;KB=d.items;$('kbStatNum').textContent=d.stats.total;$('kbStatFull').textContent=d.stats.parsed;$('kbStatCk').textContent=d.stats.pending;$('sbKbN').textContent=d.stats.total;renderKb();if($('kbPaneGov').style.display!=='none')await loadKbGov();}
function renderKb(){$('kbChips').innerHTML=['','法规依据','项目资料','案例参考'].map(t=>`<button class="btn sm ${kbType===t?'primary':''}" onclick="kbTypeChip('${t}')">${t||'全部类型'}</button>`).join('')+'<span style="width:12px"></span>'+['','现行','待核验','历史版本'].map(s=>`<button class="btn sm ${kbStatus===s?'primary':''}" onclick="kbStChip('${s}')">${s||'全部状态'}</button>`).join('')+`<button class="btn sm" onclick="kbSortToggle()">排序：${kbSort==='cited'?'被引用次数':'最近登记'}</button>`;$('kbBody').innerHTML=KB.map(s=>`<tr data-source="${s.id}"><td><b>${esc(s.name)}</b><div class="muted" style="font-size:11px">${esc(s.region)} · ${s.parsed?s.chunk_count+' 条片段':'正文待处理'}</div></td><td>${esc(s.category)}</td><td>${esc(s.doc_no||'内部资料')}</td><td>${esc(s.effective_date||'未登记')}</td><td><span class="chip ${s.status==='现行'?'green':s.status==='待核验'?'amber':'gray'}">${esc(s.status)}</span><div class="muted" style="font-size:11px">${esc(s.legal_status)}</div></td><td>${s.cite_count}</td><td><div style="display:flex;gap:5px;flex-wrap:wrap"><button class="btn sm" onclick="kbDetail(${s.id})">详情</button><button class="btn sm" onclick="askKb(${s.id})">问小安</button>${s.status==='待核验'&&s.parsed?`<button class="btn sm primary" onclick="confirmKb(${s.id})">人工核验</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有符合条件的资料</td></tr>';}
