function openKbModal(){openModal('添加知识资料',`<div class="frm"><label>资料名称 *</label><input id="kbName"><div class="row2"><div><label>资料类型 *</label><select id="kbType"><option>法规依据</option><option>项目资料</option><option>案例参考</option></select></div><div><label>适用地域 *</label><input id="kbRegion" value="厦门"></div></div><label>文号 / 标准号（法规必填）</label><input id="kbNo"><div class="row2"><div><label>生效日期</label><input id="kbDate" type="date"></div><div><label>来源 URL / 发布渠道</label><input id="kbUrl"></div></div><label>原文文件（最大20MB）*</label><input id="kbFile" type="file" accept=".pdf,.docx,.txt,.md,.html,.htm,.doc"><p class="frm-tip">上传后为待核验，成功解析后仍需人工核对原文与效力。旧版DOC须转换后重新上传。</p></div>`,'<button class="btn" onclick="closeModal()">取消</button><button id="kbSubmit" class="btn primary" onclick="submitKb()">上传并解析</button>');}
async function submitKb(){const f=$('kbFile').files[0];if(!f)return toast('请选择原文文件');const data=new FormData();for(const [key,id] of [['name','kbName'],['category','kbType'],['doc_no','kbNo'],['region','kbRegion'],['effective_date','kbDate'],['source_url','kbUrl']])data.append(key,$(id).value);data.append('file',f);$('kbSubmit').disabled=true;try{const s=await api('/api/kb/sources','POST',data);closeModal();kbType='';kbStatus='';$('kbQ').value='';await load_p5();toast('已登记待核验资料：'+s.name);}finally{if($('kbSubmit'))$('kbSubmit').disabled=false;}}
