async function submitKbConfirm(id){await api('/api/kb/sources/'+id+'/confirm','POST',{confirmed:$('kbReviewed').checked,note:$('kbReviewNote').value});closeModal();await load_p5();toast('人工核验已记录，资料已参与检索');}
async function loadKbGov(){const [pending,logs]=await Promise.all([api('/api/kb/sources?status=待核验'),api('/api/kb/changelog')]);$('kbCkCnt').textContent=pending.items.length+' 项';$('kbCkBody').innerHTML=pending.items.map(s=>`<div class="src-card"><b>${esc(s.name)}</b><p class="muted">${esc(s.parse_note||'待解析')} · ${esc(s.doc_no)}</p><button class="btn sm" onclick="kbDetail(${s.id})">详情与原文</button> ${s.parsed?`<button class="btn sm primary" onclick="confirmKb(${s.id})">人工核验</button>`:''}</div>`).join('')||'<div class="empty">没有待核验资料</div>';$('kbLogBody').innerHTML=logs.map(l=>`<div class="src-card"><b>${esc(l.name)}</b><p>${esc(l.action)} · ${esc(l.actor)} · ${esc(l.created_at)}</p><small>${esc(l.before_json)} → ${esc(l.after_json)}</small><div>${l.undone?'已撤销':!['upload_source','undo_change'].includes(l.action)?`<button class="btn sm" onclick="kbUndoModal(${l.id})">撤销管理操作</button>`:'保留追溯'}</div></div>`).join('')||'暂无变更';}
async function checkUpdate2(){const r=await api('/api/kb/check-updates','POST');$('kbUpProg').innerHTML=`<p class="frm-tip">${esc(r.method)}</p>`+r.suggestions.map(s=>`<div class="src-card"><b>${esc(s.name)}</b><p>${esc(s.rule.old_no)} → ${esc(s.rule.new_no)} · ${esc(s.rule.effective_date)}</p><small>${esc(s.rule.basis_url)}</small><div>${s.needs_change?`<button class="btn sm primary" onclick="applyKbUpdate(${s.source_id})">人工确认旧版停用</button>`:'已归档旧版，新引用已拦截'}</div></div>`).join('')+(r.suggestions.length?'':'<p>已登记关系中没有匹配的旧版资料。</p>');}
function openVersionRule(){openModal('登记已核实的版本替代关系','<div class="frm"><label>旧版文号 *</label><input id="ruleOld"><label>新版文号 *</label><input id="ruleNew"><label>替代生效日期 *</label><input type="date" id="ruleDate"><label>官方发布依据 URL / 核验记录 *</label><textarea id="ruleBasis"></textarea><p class="frm-tip">登记的是已核实的版本事实。撤销库内管理操作不会恢复已废止法律效力。</p></div>','<button class="btn primary" onclick="saveVersionRule()">保存关系并留痕</button>');}
async function saveVersionRule(){await api('/api/kb/version-rules','POST',{old_no:$('ruleOld').value,new_no:$('ruleNew').value,effective_date:$('ruleDate').value,basis_url:$('ruleBasis').value});closeModal();await checkUpdate2();toast('替代关系已登记，新引用实时校验');}
function applyKbUpdate(id){openModal('确认旧版停用','<div class="frm"><label>核验记录 *</label><textarea id="kbUpdateNote"></textarea></div>',`<button class="btn primary" onclick="submitKbUpdate(${id})">确认停用并留痕</button>`);}
async function submitKbUpdate(id){await api('/api/kb/sources/'+id+'/apply-update','POST',{confirmed:true,note:$('kbUpdateNote').value});closeModal();await load_p5();await checkUpdate2();toast('旧版已归档，历史引用快照保留');}
function kbUndoModal(id){openModal('撤销知识库管理操作','<div class="frm"><label>撤销原因 *</label><textarea id="kbUndoNote"></textarea><p class="frm-tip">仅撤销审核等管理状态，不恢复法定废止版本的引用资格，不修改已签发文书。</p></div>',`<button class="btn primary" onclick="kbRollback(${id})">确认撤销并留痕</button>`);}
async function kbRollback(id){await api('/api/kb/changelog/'+id+'/undo','POST',{confirmed:true,note:$('kbUndoNote').value});closeModal();await load_p5();toast('管理操作已撤销，法律效力限制保留');}

document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'操作未完成，请重试');e.preventDefault();});
(async()=>{const runtime=await api('/api/runtime');if(runtime.demo_generation&&localStorage.getItem('safety_demo_generation')!==runtime.demo_generation){Object.keys(localStorage).filter(k=>k.startsWith('safety_')).forEach(k=>localStorage.removeItem(k));token='';curSessId=null;localStorage.setItem('safety_demo_generation',runtime.demo_generation);}const users=(await api('/api/auth/users')).filter(u=>u.username==='AQ20260001');$('lgUser').innerHTML=users.map(u=>`<option value="${esc(u.username)}">${esc(u.display_name)} · ${esc(u.role)}（工号 ${esc(u.employee_no)}）</option>`).join('');document.querySelector('.lg-tip').textContent='王建国 · 专职安全员 · 初始密码 123456 · 操作按当前身份留痕';if(token){try{CUR_USER=await api('/api/auth/me');if(CUR_USER.username!=='AQ20260001'){await toLogin('本轮演示使用王建国身份，请重新登录');return;}applyUser();$('loginGate').classList.remove('on');go('p1');}catch{token='';localStorage.removeItem('safety_token');}}})();
